import express from 'express';

  const app = express();
  const PORT = process.env.PORT || 3000;

  const LOGO_B64 = '';

  const MOBILECONFIG = `<?xml version="1.0" encoding="UTF-8"?>
  <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
  <plist version="1.0">
  <dict>
    <key>PayloadContent</key>
    <array>
      <dict>
        <key>FullScreen</key>
        <true/>
        <key>Icon</key>
        <data></data>
        <key>IsRemovable</key>
        <true/>
        <key>Label</key>
        <string>Legacy Sports</string>
        <key>PayloadDescription</key>
        <string>Adds Legacy Sports to your Home Screen</string>
        <key>PayloadDisplayName</key>
        <string>Legacy Sports</string>
        <key>PayloadIdentifier</key>
        <string>com.legacysports.webclip</string>
        <key>PayloadType</key>
        <string>com.apple.webClip.managed</string>
        <key>PayloadUUID</key>
        <string>B2C3D4E5-F6A7-8901-BCDE-F12345678901</string>
        <key>PayloadVersion</key>
        <integer>1</integer>
        <key>Precomposed</key>
        <true/>
        <key>URL</key>
        <string>https://legacy-sports-ql8y.onrender.com</string>
      </dict>
    </array>
    <key>PayloadDescription</key>
    <string>Install Legacy Sports as a Web App on your Home Screen</string>
    <key>PayloadDisplayName</key>
    <string>Legacy Sports</string>
    <key>PayloadIdentifier</key>
    <string>com.legacysports.profile</string>
    <key>PayloadOrganization</key>
    <string>Legacy Sports</string>
    <key>PayloadType</key>
    <string>Configuration</string>
    <key>PayloadUUID</key>
    <string>A1B2C3D4-E5F6-7890-ABCD-EF1234567890</string>
    <key>PayloadVersion</key>
    <integer>1</integer>
  </dict>
  </plist>`;

  const HTML = `<!DOCTYPE html>
  <html lang="en">
  <head>
    <meta charset="UTF-8"/>
    <meta name="viewport" content="width=device-width,initial-scale=1.0"/>
    <title>Legacy Sports - Install on iPhone</title>
    <style>
      *{box-sizing:border-box;margin:0;padding:0}
      body{min-height:100vh;background:linear-gradient(135deg,#0a1628 0%,#1a2744 50%,#0d1f3c 100%);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px 16px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}
      .card{max-width:420px;width:100%;text-align:center}
      .logo{width:120px;height:120px;border-radius:28px;overflow:hidden;margin:0 auto 24px;box-shadow:0 8px 32px rgba(0,0,0,.5);background:#fff}
      .logo img{width:100%;height:100%;object-fit:cover}
      h1{color:#fff;font-size:32px;font-weight:800;margin-bottom:8px;letter-spacing:-.5px}
      .sub{color:rgba(255,255,255,.6);font-size:16px;margin-bottom:40px}
      .btn{display:block;background:linear-gradient(135deg,#e63329 0%,#ff5c38 100%);color:#fff;font-size:18px;font-weight:700;padding:18px 32px;border-radius:16px;text-decoration:none;margin-bottom:40px;box-shadow:0 4px 20px rgba(230,51,41,.4)}
      .steps{background:rgba(255,255,255,.07);border-radius:16px;padding:24px;text-align:left}
      .steps h2{color:#fff;font-size:13px;font-weight:700;margin-bottom:16px;text-transform:uppercase;letter-spacing:1px}
      .step{display:flex;align-items:flex-start;gap:12px;margin-bottom:12px}
      .step:last-child{margin-bottom:0}
      .num{width:28px;height:28px;border-radius:50%;flex-shrink:0;background:linear-gradient(135deg,#e63329,#ff5c38);color:#fff;font-size:13px;font-weight:700;display:flex;align-items:center;justify-content:center}
      .step p{color:rgba(255,255,255,.8);font-size:14px;padding-top:5px;line-height:1.4}
      .note{color:rgba(255,255,255,.3);font-size:12px;margin-top:24px}
    </style>
  </head>
  <body>
  <div class="card">
    <div class="logo"><img src="data:image/png;base64,${LOGO_B64}" alt="Legacy Sports"/></div>
    <h1>Legacy Sports</h1>
    <p class="sub">Add to your iPhone Home Screen</p>
    <a class="btn" href="/legacysports.mobileconfig">&#128242; Install on iPhone</a>
    <div class="steps">
      <h2>How to Install</h2>
      <div class="step"><div class="num">1</div><p>Tap the button above &mdash; <strong>must use Safari</strong></p></div>
      <div class="step"><div class="num">2</div><p>Tap <strong>Allow</strong> to download the profile</p></div>
      <div class="step"><div class="num">3</div><p>Go to <strong>Settings &rarr; General &rarr; VPN &amp; Device Management</strong></p></div>
      <div class="step"><div class="num">4</div><p>Tap <strong>Legacy Sports</strong> &rarr; tap <strong>Install</strong></p></div>
      <div class="step"><div class="num">5</div><p>Done! App icon appears on your Home Screen &#9989;</p></div>
    </div>
    <p class="note">Must be opened in Safari on iPhone or iPad</p>
  </div>
  </body>
  </html>`;

  app.get('/', (_req, res) => {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(HTML.replace('${LOGO_B64}', LOGO_B64));
  });

  app.get('/legacysports.mobileconfig', (_req, res) => {
    res.setHeader('Content-Type', 'application/x-apple-aspen-config');
    res.setHeader('Content-Disposition', 'attachment; filename="legacysports.mobileconfig"');
    res.send(MOBILECONFIG);
  });

  app.get('/healthz', (_req, res) => res.json({ status: 'ok' }));

  app.listen(PORT, () => console.log('Server running on port ' + PORT));
  